import sympy as S
from math import comb,prod,cos,sin,pi
from fractions import Fraction as F
from .authoring import maker,finish
from .common import section
q=maker('complex-roots-unity',['conjugation','complex rotations','roots-of-unity filters'])
i=S.I;x=S.Symbol('x')
def walks(n):
 d={(0,0):1}
 for _ in range(n):
  e={}
  for (a,b),count in d.items():
   for u,v in [(1,0),(-1,0),(0,1),(0,-1)]:e[a+u,b+v]=e.get((a+u,b+v),0)+count
  d=e
 return d.get((0,0),0)
p=[
q(1,r'If z=3+4i, find $z+25/z$.',6,[(8*i,'Subtract rather than add the conjugate.'),(6+8*i,'Treat 25/z as z.'),(3,'Report only the real part once.'),(25,'Report the squared modulus.')],[r'The squared modulus is z times its conjugate, 25.',r'Thus 25/z is the conjugate 3-4i.',r'Adding to z gives six.'],['Relate the denominator to the squared modulus.' ,'Conjugation changes the sign of the imaginary part.'],'Recognize a reciprocal as a scaled conjugate.',lambda:S.simplify(3+4*i+25/(3+4*i)),'Direct exact complex division.',2),
q(2,r'A complex number z satisfies $|z|=1$ and $z+z^{-1}=\sqrt3$. Find $z^6+z^{-6}$.',-2,[(2,'Use a full-turn angle instead of a half-turn.'),(0,'Assume the sixth powers are purely imaginary.'),(-1,'Report one sixth power rather than their sum.'),(S.sqrt(3),'Assume the original sum is unchanged under powers.')],[r'On the unit circle, z^-1 is the conjugate, so Re(z)=√3/2.',r'The two possibilities are z=√3/2±i/2, with arguments ±π/6.',r'Their sixth powers and inverse sixth powers are both -1, giving -2.'],['Use the unit-modulus condition to interpret the reciprocal.' ,'Determine the possible arguments before taking powers.'],'Combine conjugation, unit-circle geometry, and a power.',lambda:S.simplify(((S.sqrt(3)+i)/2)**6+((S.sqrt(3)-i)/2)**6),'Direct exact binomial expansion.'),
q(3,r'What is the sum of the four fifth roots of unity other than 1?',-1,[(0,'Use the sum of all five roots.'),(1,'Forget to subtract the omitted root.'),(4,'Add moduli instead of complex numbers.'),(-4,'Assume each nontrivial root has real part minus one.')],[r'The sum of all roots of z^5-1 is zero by its z⁴ coefficient.',r'One root is one.',r'The other four therefore sum to -1.'],['Use a polynomial coefficient to sum all roots.' ,'Remove the omitted root only after summing the full set.'],'Use Vieta to evaluate a symmetric complex sum.',lambda:-S.Poly(sum(x**k for k in range(5)),x).coeff_monomial(x**3),'Independent Vieta on the nontrivial-root polynomial.',2),
q(4,r'Let $\zeta_0,\ldots,\zeta_4$ be all fifth roots of unity. Find $\prod_{k=0}^{4}(2-\zeta_k)$.',31,[(32,'Omit the constant term of the root polynomial.'),(33,'Use z^5+1 instead of z^5-1.'),(16,'Use the wrong number of roots.'),(-31,'Reverse all five factors without changing the sign.')],[r'The monic polynomial with these roots is t^5-1.',r'Its root factorization is the requested product when evaluated at t=2.',r'The result is 2^5-1=31. No individual roots need to be calculated.'],['Recognize a product over every root of one polynomial.' ,'Evaluate that polynomial at the common shift.'],'Evaluate a symmetric root product directly.',lambda:S.resultant(x**5-1,2-x,x),'Independent symbolic resultant.',2),
q(5,r'Let ζ run over the six seventh roots of unity other than 1. Find $\sum 1/(1-\zeta)$.',3,[(6,'Count one for every root instead of every inverse pair.'),(F(1,2),'Report the average contribution rather than the sum.'),(0,'Assume the reciprocal sum inherits the ordinary root sum.'),(-3,'Reverse every denominator.')],[r'The nontrivial roots pair as ζ and ζ^-1, with no root equal to its own inverse.',r'For each pair, $1/(1-\zeta)+1/(1-\zeta^{-1})=1$, obtained by combining fractions.',r'There are three pairs, so the sum is three. None of the denominators vanishes.'],['Pair roots with their reciprocals.' ,'Simplify one pair before summing all six terms.'],'Use inverse-pair cancellation on a rational root sum.',lambda:S.diff(sum(x**k for k in range(7)),x).subs(x,1)/sum(x**k for k in range(7)).subs(x,1),'Independent logarithmic-derivative identity Q′(1)/Q(1).'),
q(6,r'How many solutions of $z^{12}=1$ have strictly positive real part?',5,[(6,'Include one of the imaginary-axis boundary roots.'),(7,'Include both imaginary-axis roots.'),(4,'Exclude the positive real root one.'),(12,'Use positive modulus instead of positive real part.')],[r'The twelve roots have arguments kπ/6 for k=0,...,11.',r'Positive real part means cos(kπ/6)>0, selecting k=0,1,2,10,11.',r'There are five; k=3 and 9 lie on the imaginary axis and are excluded.'],['Place the roots at equally spaced angles on the unit circle.' ,'Treat roots on the boundary separately from roots in the open half-plane.'],'Count roots in a strict angular region.',lambda:sum(bool(S.cos(S.pi*k/6)>0) for k in range(12)),'Exact unit-circle coordinate signs.',2),
q(7,r'Complex numbers z satisfy $|z-1|=|z+1|$ and $|z-2i|=\sqrt5$. Find the product of all such z.',1,[(-1,'Forget that i²=-1 when multiplying the imaginary coordinates.'),(4,'Use the sum of the imaginary coordinates as a product.'),(5,'Use the circle radius squared.'),(-4,'Confuse the center sum with the product.')],[r'The first locus is the perpendicular bisector of -1 and 1, so z=iy for real y.',r'The second condition gives (y-2)²=5, hence y=2±√5.',r'The product of the two z values is i²(4-5)=1.'],['Interpret each modulus equation as a geometric locus.' ,'Intersect the imaginary axis with the given circle.'],'Translate complex-distance conditions into intersecting loci.',lambda:S.expand(i*(2+S.sqrt(5))*i*(2-S.sqrt(5))),'Exact circle-line roots substituted and multiplied.'),
q(8,r'The point represented by 1+i is rotated 90° counterclockwise about the point 2+i. What complex number represents its image?',2,[(2+2*i,'Rotate clockwise instead.'),(-1+i,'Rotate about the origin instead of the stated center.'),(1+2*i,'Translate without the correct rotation.'),(3+i,'Reflect across the center instead of quarter-turning.')],[r'Subtract the center: (1+i)-(2+i)=-1.',r'Multiply the displacement by i for a counterclockwise quarter-turn, giving -i.',r'Add the center back: 2+i-i=2.'],['Translate the rotation center to zero.' ,'Multiply the displacement by i, then restore the center.'],'Compose translation and complex multiplication.',lambda:S.Point(1,1).rotate(S.pi/2,S.Point(2,1)).x+i*S.Point(1,1).rotate(S.pi/2,S.Point(2,1)).y,'Independent planar rotation.',2),
q(9,r'The first two consecutive vertices of a square, listed counterclockwise, are 1+2i and 4+6i. What is the squared modulus of its center?',F(61,2),[(25,'Report the side length squared.'),(F(89,4),'Use the midpoint of the given side as the square center.'),(61,'Forget to average opposite vertices.'),(F(53,2),'Use the square on the opposite side of the directed edge.')],[r'The directed edge is 3+4i. Turning it counterclockwise gives i(3+4i)=-4+3i.',r'The third vertex is (4+6i)+(-4+3i)=9i, so the center is the midpoint of 1+2i and 9i: 1/2+(11/2)i.',r'Its squared modulus is 1/4+121/4=61/2. The orientation selects one of two possible squares.'],['Use multiplication by i to obtain the next directed edge.' ,'The center is the midpoint of opposite, not adjacent, vertices.'],'Use orientation-sensitive complex geometry.',lambda:abs((1+2*i+9*i)/2)**2,'Independent opposite-vertex midpoint coordinates.'),
q(10,r'Evaluate $(1+i)^{20}$.',-1024,[(1024,'Ignore the final argument.'),(1024*i,'Use an argument one quarter-turn away.'),(-32,'Use modulus √2 without raising it through all twenty powers.'),(0,'Assume powers cancel because the real and imaginary parts begin equal.')],[r'Write 1+i=√2(cos(π/4)+i sin(π/4)).',r'The twentieth power has modulus (√2)^20=1024 and argument 5π.',r'Since cos5π=-1 and sin5π=0, the value is -1024.'],['Separate modulus from argument.' ,'Reduce the multiplied argument modulo a full turn.'],'Apply polar powers with independent magnitude and angle tracking.',lambda:S.expand((1+i)**20),'Direct exact binomial expansion.',2),
q(11,r'Find $\binom{12}0+\binom{12}4+\binom{12}8+\binom{12}{12}$.',992,[(1024,'Assume the four residue classes have exactly equal coefficient sums.'),(4096,'Sum the entire binomial row.'),(960,'Use the wrong sign for the imaginary evaluations.'),(2048,'Filter only parity rather than residue modulo four.')],[r'For P(t)=(1+t)^12, the average [P(1)+P(-1)+P(i)+P(-i)]/4 retains exactly exponents divisible by four.',r'These values are 4096,0,-64,-64.',r'The sum is (4096-128)/4=992. The complex terms correct the tempting equal-quarter estimate.'],['Evaluate at the fourth roots of unity to filter exponents.' ,'Averaging cancels powers whose exponent is not divisible by four.'],'Use a roots-of-unity filter for a coefficient residue class.',lambda:sum(comb(12,k) for k in range(0,13,4)),'Independent direct binomial coefficient sum.'),
q(12,r'A walk starts at 0 in the complex plane. Each of ten steps adds one of 1,-1,i,-i. How many step sequences return to 0?',63504,[(252,'Choose only the positions of one direction without assigning all four.'),(1048576,'Count all walks.'),(30240,'Count only one horizontal-vertical balance split.'),(31752,'Identify a walk with its reversal.')],[r'A returning walk has k east and k west steps, and 5-k north and 5-k south steps.',r'For fixed k, the count is 10!/[k!²(5-k)!²]=C(10,5)C(5,k)².',r'Sum over k and use Vandermonde: C(10,5)·C(10,5)=252²=63504.'],['Return to zero requires separate horizontal and vertical balance.' ,'Partition by the number of steps in one horizontal direction.'],'Connect complex displacement to a balanced-word identity.',lambda:walks(10),'Independent dynamic programming on integer coordinate displacements.'),
q(13,r'A regular heptagon is inscribed in the unit circle. From one vertex, sum the squares of the distances to the other six vertices.',14,[(7,'Omit the cross-term contribution of the other roots.'),(12,'Assume the other six roots sum to zero.'),(28,'Double every chord-square contribution.'),(6,'Add unit radii instead of chord lengths.')],[r'Rotate the chosen vertex to 1. For another unit root ζ, |1-ζ|²=2-ζ-conjugate(ζ).',r'The six other roots sum to -1, and their conjugates also sum to -1.',r'The total is 12-(-1)-(-1)=14. This avoids calculating six individual chord lengths.'],['Express a chord length squared using conjugation.' ,'Sum the roots before evaluating individual angles.'],'Combine a norm identity with a symmetric root sum.',lambda:round(sum(2-2*cos(2*pi*k/7) for k in range(1,7))),'Independent numerical chord-square sum supports the exact root-sum proof.'),
q(14,r'A regular heptagon is inscribed in the unit circle. From one vertex, multiply the distances to all other vertices. What is the product?',7,[(1,'Assume unit radii imply unit chords.'),(6,'Add the number of distances instead of multiplying.'),(49,'Report the square of the product.'),(14,'Use the squared-distance sum identity instead.')],[r'Let the chosen vertex be 1 and the other roots be ζ. The polynomial with those six roots is Q(t)=(t^7-1)/(t-1)=1+t+...+t^6.',r'Evaluating at t=1 gives product(1-ζ)=Q(1)=7.',r'Taking absolute values changes the complex product into the requested product of chord lengths, still seven.'],['Remove the known root from the seventh-root polynomial.' ,'Evaluate the remaining root product at the chosen vertex, then take moduli.'],'Convert a geometric product into a polynomial value.',lambda:round(prod(2*sin(pi*k/7) for k in range(1,7))),'Independent numerical product of exact chord formulas supports the polynomial proof.')]
e=[
q(101,r'Let z=2+3i. Find $z+13/z$.',4,[(6*i,'Subtract the conjugate.'),(4+6*i,'Replace 13/z by z instead of its conjugate.'),(13,'Report the squared modulus.'),(2,'Report the real part once.')],[r'The relation z·conjugate(z)=|z|²=13 means 13/z=conjugate(z). This avoids a long complex division.',r'The conjugate is 2-3i, so the sum is four.',r'If the numerator had not been |z|², the reciprocal would be a different scalar multiple of the conjugate.',r'The underlying identity 1/z=conjugate(z)/|z|² requires z≠0. On the unit circle it simplifies further to 1/z=conjugate(z).'],['Compare the numerator with the squared modulus.' ,'Use the conjugate reciprocal identity.'],'Explain when a reciprocal becomes a conjugate.',lambda:S.simplify(2+3*i+13/(2+3*i)),'Independent exact division.',2),
q(102,r'Find the sum of the coefficients of $x^k$ in $(1+x)^6$ for k divisible by three.',22,[(F(64,3),'Assume exact equality among three residue classes.'),(32,'Filter parity instead.'),(20,'Keep only the central coefficient.'),(64,'Sum all coefficients.')],[r'Let ω be a nonreal cube root of unity. Since 1+ω+ω²=0, the average [P(1)+P(ω)+P(ω²)]/3 keeps exactly powers divisible by three.',r'For P(t)=(1+t)^6, P(1)=64. Also 1+ω=-ω² and 1+ω²=-ω, so both other evaluations are one.',r'The filtered sum is (64+1+1)/3=22.',r'A direct check gives C(6,0)+C(6,3)+C(6,6)=1+20+1=22. The filter becomes useful when many terms or weighted coefficients are involved.'],['Average evaluations at the three cube roots of unity.' ,'Check what this average does to a single monomial first.'],'Derive a coefficient filter from a geometric-series cancellation.',lambda:sum(comb(6,k) for k in [0,3,6]),'Independent direct coefficient sum.')]
finish('complex-roots-unity','AMC 12: complex geometry & roots of unity','AMC 12 extensions','complex binomial polynomial-structure combinatorial-identities log-trig-synthesis',44,'653–674',
 [r'Complex numbers provide both algebra and a plane geometry. Addition translates, multiplication rotates and scales, conjugation reflects, and modulus measures distance. Roots of unity connect these geometric operations to polynomial identities and counting filters.',r'The useful representation depends on the target. Rectangular form is effective for distances and loci; polar form is effective for powers; a root polynomial is effective for symmetric sums and products. Switching forms is often the decisive move.'],
 [section('Use conjugation and geometry together',r'For z=x+iy, the product z·conjugate(z)=x²+y² is the squared modulus. Hence 1/z=conjugate(z)/|z|² when z≠0. On the unit circle, the reciprocal is exactly the conjugate, which turns z+1/z into twice the real part.',r'A modulus equation |z-a|=|z-b| describes a perpendicular bisector, while |z-c|=r describes a circle. Translate these into coordinates only after identifying the loci. The geometric interpretation predicts the possible number of intersections and helps detect an extraneous algebraic solution.',r'Multiplication by i is a counterclockwise quarter-turn about the origin. For a different center c, use c+i(z-c). The order of translating, rotating, and translating back matters. For a square, orientation decides which side of a directed edge contains the remaining vertices.'),
 section('Choose polar form for powers and polynomial form for roots',r'If z=r(cosθ+i sinθ), its nth power has modulus r^n and argument nθ modulo 2π. Track these separately; a correct angle with an incorrect magnitude is still a wrong complex number. Roots of unity have modulus one and equally spaced arguments.',r'The nth roots of unity are exactly the roots of t^n-1. Vieta gives their total sum, and evaluating the root factorization gives products with a common shift. Excluding the root one replaces this polynomial by 1+t+...+t^(n-1).',r'Inverse roots can be paired to simplify rational expressions. For a nontrivial root ζ, the pair 1/(1-ζ)+1/(1-ζ^-1) equals one. Check whether any root is its own inverse and whether a denominator vanishes; these endpoint cases determine whether a clean pairing is valid.'),
 section('Filter coefficients and sum geometric quantities',r'For an mth root ω with exact order m, the average of 1,ω^k,...,ω^((m-1)k) is one if m divides k and zero otherwise. Apply this to each monomial of a polynomial to retain one exponent residue class. The cancellation follows from a finite geometric sum, so no numerical approximation is needed.',r'Complex walk problems can often return to ordinary counting after real and imaginary displacements are separated. A return to zero requires equal east-west counts and equal north-south counts. Partition by one count, then recognize the resulting binomial identity.',r'For a regular polygon on the unit circle, a chord from one to ζ has squared length 2-ζ-conjugate(ζ). Summing uses the root sum, while multiplying uses the root polynomial evaluated at one after removing its trivial root. These methods avoid calculating every chord and show why algebraic symmetry can simplify a geometric quantity.')],
 ['Move between rectangular, polar, and polynomial representations.','Use complex multiplication for orientation-sensitive geometry.','Derive roots-of-unity filters and apply them to coefficients and polygon distances.'],
 [r'Multiply by the conjugate to derive the reciprocal identity.',r'Expand t^n-1 as a product over its roots and evaluate at a chosen shift.',r'Sum the finite geometric progression of root powers to prove the exponent filter.'],
 'Modulus and real part are different quantities. Roots on the imaginary axis have positive modulus but zero real part, and strict half-plane conditions exclude them.',e,p,
 dict(prompt=r'For P(t)=(1+t)^8, use P(1),P(-1),P(i),P(-i) to find the sum of coefficients whose exponents are divisible by four.',answer=r'The sum is 72.',steps=[r'The four evaluations are 256,0,16,16.',r'Their average is (256+16+16)/4=72, agreeing with 1+C(8,4)+1.']),
 ['conjugate reciprocals','complex affine rotations','root-polynomial products','roots-of-unity filters'],
 [(r'\frac1z=\frac{\overline z}{|z|^2}','Conjugate reciprocal','replacing complex division with conjugation and a real scale','$z\\ne0$; for $|z|=1$ the reciprocal equals the conjugate.'),(r'z\mapsto c+e^{i\theta}(z-c)','Complex rotation about a center','rotating a point while preserving its distance from c','θ is the counterclockwise angle in radians; c is the fixed center.'),(r'\prod_{k=0}^{n-1}(t-\omega^k)=t^n-1','Unity-root factorization','evaluating symmetric products over all nth roots of unity','ω has exact order n, so its powers enumerate every root once.'),(r'\frac1m\sum_{j=0}^{m-1}\omega^{jk}=\begin{cases}1&m\mid k\\0&m\nmid k\end{cases}','Roots-of-unity filter','retaining polynomial coefficients in an exponent residue class','ω has exact order m; k is an integer.')], 'complex',track=12)
